target.css:
:root {
  --ink: #13263a;
  --navy: #183b56;
  --sky: #dceff4;
  --paper: #fffdf7;
  --line: #b8d0d5;
  --aqua: #42c5bd;
  --lime: #c9e95b;
  --amber: #f5b544;
  --coral: #e96b58;
  --muted: #657d89;
}

* {
  box-sizing: border-box;
}

.launch-card {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--navy);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 13px;
  border-bottom: 1px solid var(--line);
  background: var(--sky);
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--navy);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.dashboard {
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  min-height: 154px;
}

.telemetry-panel,
.ascent-panel {
  padding: 14px 16px;
}

.telemetry-panel {
  border-right: 1px solid var(--line);
}

h2 {
  font-size: 12px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.reading-list {
  display: grid;
  gap: 7px;
  margin: 11px 0 0;
  padding: 0;
  list-style: none;
}

.reading-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

.reading-list li:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.reading-list strong {
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-heading span {
  color: var(--aqua);
  font-size: 11px;
  font-weight: 800;
}

.altitude-figure {
  margin: 13px 0 0;
}

.bar-stack {
  display: flex;
  align-items: end;
  gap: 7px;
  height: 65px;
  padding: 7px 8px;
  border-radius: 9px;
  background: var(--navy);
}

.bar {
  display: block;
  flex: 1;
  border-radius: 3px 3px 1px 1px;
}

.bar-one {
  height: 28%;
  background: var(--aqua);
}

.bar-two {
  height: 49%;
  background: var(--lime);
}

.bar-three {
  height: 72%;
  background: var(--amber);
}

.bar-four {
  height: 94%;
  background: var(--coral);
}

figcaption {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--amber);
}

button {
  border: 1px solid var(--navy);
  border-radius: 7px;
  padding: 7px 10px;
  background: var(--paper);
  color: var(--navy);
  font-size: 11px;
  font-weight: 800;
}

